            }
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        long a = fs.nextLong();
        long b = fs.nextLong();
        long p = fs.nextLong();
        long x = fs.nextLong();

        long period = p * (p - 1);
        long fullPeriods = x / period;
        long remainder = x % period;
        long answer = fullPeriods * (p - 1);

        long inverseA = modPow(a, p - 2, p);
        long c = b;

        for (long k = 0; k < p - 1; k++) {
            long t = (k - c) % p;
            if (t < 0) {
                t += p;
            }

            long n = k + (p - 1) * t;
            if (n >= 1 && n <= remainder) {
                answer++;
            }

            c = c * inverseA % p;
        }

        System.out.println(answer);
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int position;
        private int length;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (position >= length) {
                length = in.read(buffer);
                position = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[position++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
