import java.io.*;

public class Main {
    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) != 0) result = result * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }

    static int multiplicativeOrder(int a, int p) {
        int order = p - 1;
        int value = p - 1;

        for (int factor = 2; (long) factor * factor <= value; factor++) {
            if (value % factor == 0) {
                while (value % factor == 0) value /= factor;
                while (order % factor == 0 &&
                       modPow(a, order / factor, p) == 1) {
                    order /= factor;
                }
            }
        }

        if (value > 1) {
            while (order % value == 0 &&
                   modPow(a, order / value, p) == 1) {
                order /= value;
            }
        }
        return order;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int a = fs.nextInt();
        int b = fs.nextInt();
        int p = fs.nextInt();
        long x = fs.nextLong();

        int order = multiplicativeOrder(a, p);
        long period = (long) p * order;
        long inverseA = modPow(a, p - 2L, p);
        long inverseOrder = modPow(order, p - 2L, p);

        long requiredResidue = b;
        long answer = 0;

        for (int exponentResidue = 0; exponentResidue < order; exponentResidue++) {
            long difference = (requiredResidue - exponentResidue) % p;
            if (difference < 0) difference += p;

            long k = difference * inverseOrder % p;
            long first = exponentResidue + (long) order * k;

            if (first == 0) first = period;
            if (first <= x) {
                answer += 1 + (x - first) / period;
            }

            requiredResidue = requiredResidue * inverseA % p;
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

